"""Jalankan sekali: python pasang_template.py -> membuat folder templates + 6 file HTML."""
import os

FILES = {
    'base.html': '<!DOCTYPE html>\n<html lang="id">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>{% block title %}SuratKu{% endblock %}</title>\n  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">\n  <link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet">\n  <style>\n    body { background:#f1f5f9; min-height:100vh; }\n    .navbar { background:linear-gradient(135deg,#1e1b4b,#4338ca); }\n    .card { border:0; border-radius:16px; box-shadow:0 6px 20px rgba(30,27,75,.08); }\n    .btn-primary { --bs-btn-bg:#4338ca; --bs-btn-border-color:#4338ca; --bs-btn-hover-bg:#3730a3; --bs-btn-hover-border-color:#3730a3; }\n    .tpl-card { transition:transform .2s, box-shadow .2s; text-decoration:none; color:inherit; }\n    .tpl-card:hover { transform:translateY(-5px); box-shadow:0 14px 30px rgba(67,56,202,.22); color:inherit; }\n    .tpl-icon { width:56px; height:56px; border-radius:16px; display:flex; align-items:center; justify-content:center;\n                font-size:1.7rem; background:#e0e7ff; color:#4338ca; }\n    @media print { .no-print { display:none !important; } body { background:#fff; } }\n  </style>\n</head>\n<body>\n<nav class="navbar navbar-expand navbar-dark mb-4 no-print">\n  <div class="container">\n    <a class="navbar-brand fw-bold" href="{{ url_for(\'index\') }}"><i class="bi bi-file-earmark-text-fill me-2"></i>SuratKu</a>\n    <div class="navbar-nav ms-auto">\n      <a class="nav-link {{ \'active fw-semibold\' if request.endpoint == \'index\' }}" href="{{ url_for(\'index\') }}"><i class="bi bi-grid-fill"></i> Beranda</a>\n      <a class="nav-link {{ \'active fw-semibold\' if request.endpoint == \'arsip\' }}" href="{{ url_for(\'arsip\') }}"><i class="bi bi-archive-fill"></i> Arsip</a>\n    </div>\n  </div>\n</nav>\n<main class="container pb-5">\n  {% for kategori, pesan in get_flashed_messages(with_categories=true) %}\n    <div class="alert alert-{{ kategori }} alert-dismissible fade show no-print">{{ pesan }}<button class="btn-close" data-bs-dismiss="alert"></button></div>\n  {% endfor %}\n  {% block content %}{% endblock %}\n</main>\n<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>\n</body>\n</html>\n',
    '_kertas.html': '<style>\n  .kertas { background:#fff; max-width:794px; margin:0 auto; padding:48px 56px; min-height:600px; font-family:"Times New Roman",serif;\n            font-size:12pt; line-height:1.5; color:#000; box-shadow:0 8px 30px rgba(0,0,0,.15); border-radius:4px; }\n  .kertas .kop { text-align:center; border-bottom:3px double #000; padding-bottom:8px; margin-bottom:18px; }\n  .kertas .kop h5 { margin:0; font-weight:700; text-transform:uppercase; letter-spacing:1px; }\n  .kertas .kosong { background:#fef3c7; color:#92400e; font-size:.85em; }\n  .kertas p { margin:0 0 10px; text-align:justify; }\n  .kertas td { padding:0 8px 0 0; vertical-align:top; }\n  @media print { .kertas { box-shadow:none; padding:0; max-width:none; } }\n</style>\n<div class="kertas" id="kertas"></div>\n<script>\n  function renderKertas(tpl, d) {\n    const esc = s => String(s).replace(/[&<>"\']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#39;"}[c]));\n    const tglID = s => { const t = new Date(s + "T00:00:00"); return isNaN(t) ? s :\n      t.toLocaleDateString("id-ID", { day:"numeric", month:"long", year:"numeric" }); };\n    const tipe = {}; tpl.fields.forEach(f => tipe[f[0]] = f[2]);\n    const isi = txt => txt.replace(/\\{(\\w+)\\}/g, (m, k) => {\n      const v = (d[k] || "").trim();\n      return v ? esc(tipe[k] === "date" ? tglID(v) : v) : `<span class="kosong">[${k}]</span>`;\n    });\n    const t = d.tanggal ? new Date(d.tanggal + "T00:00:00") : new Date();\n    const romawi = ["I","II","III","IV","V","VI","VII","VIII","IX","X","XI","XII"][t.getMonth()];\n    const nomor = d.nomor || `...../${tpl.kode}/${romawi}/${t.getFullYear()}`;\n    const paragraf = isi(tpl.isi).split("\\n\\n").map(p => {\n      const baris = p.split("\\n");\n      if (baris.length > 1 && baris.every(b => b.includes(" : ")))\n        return "<table>" + baris.map(b => { const [a, ...c] = b.split(" : ");\n          return `<tr><td>${a}</td><td>:</td><td>${c.join(" : ")}</td></tr>`; }).join("") + "</table><div style=\'height:10px\'></div>";\n      return "<p>" + baris.join("<br>") + "</p>";\n    }).join("");\n    document.getElementById("kertas").innerHTML = `\n      ${d.instansi ? `<div class="kop"><h5>${esc(d.instansi)}</h5><div>${esc(d.alamat || "")}</div></div>` : ""}\n      <div style="text-align:right">${esc(d.kota || "")}, ${d.tanggal ? tglID(d.tanggal) : ""}</div>\n      <table style="margin:10px 0"><tr><td>Nomor</td><td>:</td><td>${esc(nomor)}</td></tr>\n        <tr><td>Hal</td><td>:</td><td><b>${isi(tpl.hal)}</b></td></tr></table>\n      <p>Kepada Yth.<br>${isi(tpl.kepada).replace(/\\n/g, "<br>")}</p>\n      ${paragraf}\n      <div style="margin-top:30px; margin-left:55%">Hormat kami,<br><br><br><br>\n        <b><u>${esc(d.ttd_nama || "")}</u></b><br>${esc(d.ttd_jabatan || "")}</div>`;\n  }\n</script>\n',
    'index.html': '{% extends "base.html" %}\n{% block content %}\n<div class="p-4 p-md-5 mb-4 rounded-4 text-white" style="background:linear-gradient(135deg,#4338ca,#7c3aed)">\n  <h1 class="fw-bold">Buat surat resmi dalam hitungan detik <i class="bi bi-lightning-charge-fill text-warning"></i></h1>\n  <p class="mb-0 opacity-75 fs-5">Pilih template, isi data, lihat pratinjau langsung, lalu cetak atau simpan ke arsip dengan nomor surat otomatis.</p>\n</div>\n\n<div class="row g-3 mb-4">\n  {% for label, nilai, ikon in [("Total Surat", total, "bi-files"), ("Surat Bulan Ini", bulan_ini, "bi-calendar-check"), ("Template Tersedia", surat|length, "bi-layout-text-window")] %}\n  <div class="col-md-4"><div class="card p-3 d-flex flex-row align-items-center gap-3">\n    <div class="tpl-icon" style="width:48px;height:48px;font-size:1.3rem"><i class="bi {{ ikon }}"></i></div>\n    <div><div class="h3 mb-0 fw-bold">{{ nilai }}</div><small class="text-muted">{{ label }}</small></div>\n  </div></div>\n  {% endfor %}\n</div>\n\n<h2 class="h5 fw-bold mb-3">Pilih Jenis Surat</h2>\n<div class="row g-3 mb-4">\n  {% for key, t in surat.items() %}\n  <div class="col-sm-6 col-lg-3">\n    <a href="{{ url_for(\'buat\', jenis=key) }}" class="card tpl-card h-100 p-4">\n      <div class="tpl-icon mb-3"><i class="bi {{ t.ikon }}"></i></div>\n      <h3 class="h6 fw-bold">{{ t.nama }}</h3>\n      <span class="badge text-bg-light border align-self-start">{{ t.kategori }}</span>\n      <small class="text-muted mt-3">{{ per_jenis.get(key, 0) }} surat dibuat</small>\n    </a>\n  </div>\n  {% endfor %}\n</div>\n\n<div class="card"><div class="card-body">\n  <h2 class="h5 fw-bold mb-3">Surat Terbaru</h2>\n  <ul class="list-group list-group-flush">\n    {% for r in terbaru %}\n    <li class="list-group-item d-flex justify-content-between align-items-center">\n      <div><a class="fw-medium text-decoration-none" href="{{ url_for(\'lihat\', sid=r.id) }}">{{ r.judul }}</a>\n        <div class="small text-muted">{{ r.nomor }} &bull; {{ r.dibuat }}</div></div>\n      <a href="{{ url_for(\'lihat\', sid=r.id) }}" class="btn btn-sm btn-outline-primary">Buka</a>\n    </li>\n    {% else %}\n    <li class="list-group-item text-center text-muted py-4">Belum ada surat. Pilih template di atas untuk memulai.</li>\n    {% endfor %}\n  </ul>\n</div></div>\n{% endblock %}\n',
    'form.html': '{% extends "base.html" %}\n{% block title %}{{ tpl.nama }} - SuratKu{% endblock %}\n{% block content %}\n<div class="d-flex align-items-center gap-3 mb-3 no-print">\n  <a href="{{ url_for(\'index\') }}" class="btn btn-outline-secondary btn-sm"><i class="bi bi-arrow-left"></i></a>\n  <h1 class="h4 fw-bold mb-0">{{ tpl.nama }}</h1>\n</div>\n<div class="row g-4">\n  <div class="col-lg-5 no-print">\n    <form class="card p-4" id="form" method="post" action="{{ url_for(\'simpan\', jenis=jenis) }}">\n      <h2 class="h6 fw-bold text-primary">Isi Surat</h2>\n      {% for k, label, tipe in tpl.fields %}\n      <div class="mb-2"><label class="form-label small mb-1">{{ label }}</label>\n        {% if tipe == \'textarea\' %}<textarea class="form-control" name="{{ k }}" rows="4" required>{{ nilai.get(k, \'\') }}</textarea>\n        {% else %}<input class="form-control" type="{{ tipe }}" name="{{ k }}" value="{{ nilai.get(k, \'\') }}" {{ \'min=1\' if tipe == \'number\' }} required>{% endif %}\n      </div>\n      {% endfor %}\n      <hr><h2 class="h6 fw-bold text-primary">Kop &amp; Tanda Tangan</h2>\n      {% for k, label, tipe in common %}\n      <div class="mb-2"><label class="form-label small mb-1">{{ label }}</label>\n        <input class="form-control" type="{{ tipe }}" name="{{ k }}" value="{{ nilai.get(k, \'\') }}" {{ \'required\' if k == \'ttd_nama\' }}></div>\n      {% endfor %}\n      <button class="btn btn-primary btn-lg mt-3"><i class="bi bi-save"></i> Simpan &amp; Buat Nomor Surat</button>\n    </form>\n  </div>\n  <div class="col-lg-7">\n    <div class="small text-muted mb-2 no-print"><i class="bi bi-eye"></i> Pratinjau langsung (kolom kuning = belum diisi)</div>\n    {% include "_kertas.html" %}\n  </div>\n</div>\n<script>\n  const TPL = {{ tpl|tojson }};\n  const form = document.getElementById("form");\n  const perbarui = () => renderKertas(TPL, Object.fromEntries(new FormData(form)));\n  form.addEventListener("input", perbarui);\n  perbarui();\n</script>\n{% endblock %}\n',
    'view.html': '{% extends "base.html" %}\n{% block title %}{{ row.nomor }} - SuratKu{% endblock %}\n{% block content %}\n<div class="d-flex flex-wrap gap-2 mb-3 no-print">\n  <a href="{{ url_for(\'arsip\') }}" class="btn btn-outline-secondary"><i class="bi bi-arrow-left"></i> Arsip</a>\n  <button class="btn btn-primary" onclick="window.print()"><i class="bi bi-printer-fill"></i> Cetak / Simpan PDF</button>\n  <a href="{{ url_for(\'buat\', jenis=row.jenis) }}" class="btn btn-outline-primary"><i class="bi bi-plus-lg"></i> Buat Baru</a>\n</div>\n{% include "_kertas.html" %}\n<script>renderKertas({{ tpl|tojson }}, {{ data|tojson }});</script>\n{% endblock %}\n',
    'arsip.html': '{% extends "base.html" %}\n{% block title %}Arsip Surat - SuratKu{% endblock %}\n{% block content %}\n<div class="card"><div class="card-body">\n  <h1 class="h4 fw-bold mb-3"><i class="bi bi-archive-fill text-primary"></i> Arsip Surat</h1>\n  <form method="get" class="row g-2 mb-3">\n    <div class="col-md-7"><input class="form-control" name="q" value="{{ q }}" placeholder="Cari nomor, jenis, nama, atau isi surat..."></div>\n    <div class="col-md-3">\n      <select class="form-select" name="jenis" onchange="this.form.submit()">\n        <option value="">Semua jenis</option>\n        {% for key, t in surat.items() %}<option value="{{ key }}" {{ \'selected\' if key == jenis }}>{{ t.nama }}</option>{% endfor %}\n      </select>\n    </div>\n    <div class="col-md-2 d-grid"><button class="btn btn-primary"><i class="bi bi-search"></i> Cari</button></div>\n  </form>\n  <div class="table-responsive"><table class="table align-middle">\n    <thead><tr><th>Nomor</th><th>Jenis</th><th>Tanggal</th><th class="text-end">Aksi</th></tr></thead>\n    <tbody>\n    {% for r in rows %}\n    <tr>\n      <td class="fw-medium">{{ r.nomor }}</td><td>{{ r.judul }}</td><td>{{ r.dibuat }}</td>\n      <td class="text-end">\n        <a class="btn btn-sm btn-outline-primary" href="{{ url_for(\'lihat\', sid=r.id) }}"><i class="bi bi-eye"></i></a>\n        <form method="post" action="{{ url_for(\'hapus\', sid=r.id) }}" class="d-inline" onsubmit="return confirm(\'Hapus surat {{ r.nomor }}?\')">\n          <button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form>\n      </td>\n    </tr>\n    {% else %}\n    <tr><td colspan="4" class="text-center text-muted py-4">Tidak ada surat yang cocok.</td></tr>\n    {% endfor %}\n    </tbody></table></div>\n</div></div>\n{% endblock %}\n',
}

folder = os.path.join(os.path.dirname(os.path.abspath(__file__)), "templates")
os.makedirs(folder, exist_ok=True)
for nama, teks in FILES.items():
    with open(os.path.join(folder, nama), "w", encoding="utf-8", newline="\n") as f:
        f.write(teks)
    print("dibuat:", os.path.join("templates", nama))
print("Selesai! Sekarang jalankan: python app.py")
